public enum ServerSettingsError: Error, Equatable, Sendable {
    /// Tokens are a single word, as generated by `openssl rand -base64 32`.
    case invalidToken
}

/// Where to sync and the bearer token to sync with.
public struct ServerSettings: Sendable, Equatable {
    public let url: ServerURL
    public let token: String

    public init(url: ServerURL, token: String) throws(ServerSettingsError) {
        let trimmed = token.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, !trimmed.contains(where: \.isWhitespace) else {
            throw .invalidToken
        }
        self.url = url
        self.token = trimmed
    }
}
